import{_ as a,o as e,c as d,ae as r}from"./chunks/framework.DQC_QtFV.js";const _=JSON.parse('{"title":"安全","description":"","frontmatter":{},"headers":[],"relativePath":"guide/console/safety.md","filePath":"guide/console/safety.md","lastUpdated":1793162416000}'),o={name:"guide/console/safety.md"};function s(h,t,l,n,i,c){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="安全" tabindex="-1">安全 <a class="header-anchor" href="#安全" aria-label="Permalink to &quot;安全&quot;">​</a></h1><p>安全页四张卡片：谁能使唤它、出口审查问什么、沙箱能到哪些域名、最近拦了什么。</p><h2 id="系统管理员" tabindex="-1">系统管理员 <a class="header-anchor" href="#系统管理员" aria-label="Permalink to &quot;系统管理员&quot;">​</a></h2><p>管理员只能是私聊（c2c）好友；管理员说的话视为老板本人说的。点头像看资料： uid、在哪些群、各是什么身份，可以移除。<strong>至少要有一个管理员</strong>， 否则机器人一轮都不开始（消息照常镜像，日志照常走）。候选人列表通过驱动解析名字， 密钥缺失或无效时页面会说明，而不是给一个空列表。</p><h2 id="出口审查-jev" tabindex="-1">出口审查（Jev） <a class="header-anchor" href="#出口审查-jev" aria-label="Permalink to &quot;出口审查（Jev）&quot;">​</a></h2><p>每条要发出的气泡都过这些问题；概率超过阈值就拦下。点一行改它的阈值和额外判断， 问题原文在机器人代码里，这里只读。</p><table tabindex="0"><thead><tr><th>问题</th><th>检查什么</th><th>阈值</th></tr></thead><tbody><tr><td>泄露密钥</td><td>会不会把完整的密钥、令牌、密码或验证码说出去</td><td>0-1</td></tr><tr><td>没标引用</td><td>说到具体的事或人却没标引用（公共常识不用引）</td><td>0-1</td></tr><tr><td>自我重复</td><td>是不是把这个会话里自己刚说过的话又说了一遍</td><td>0-1</td></tr></tbody></table><p>每行还有模式：关闭 / 只记录不生效 / 启用。默认 泄露密钥 始终在问， 自我重复 从 只记录不生效 上线，没标引用 默认关着——打开它之前， 先在 <a href="./logs.html">日志</a> 里看它想拦什么。</p><p>还有一道检查不在这里：引用别处标着私聊或机密的内容由宿主直接拦下，不问 Jev， 所以它没有行、也没有阈值。</p><h2 id="网络" tabindex="-1">网络 <a class="header-anchor" href="#网络" aria-label="Permalink to &quot;网络&quot;">​</a></h2><p>沙箱唯一的外网出口是机器人的出口代理。两个名单之外的域名由 Jev 现场判定： 放行进放行名单、拒绝进拦截名单、Jev 不可达时拒绝。卡片一行显示两个名单各多少条， 管理 打开名单：每条带域名、判定、加进来的时间，以及（代理判定的）问它的那条命令和工具。 来源有三种：Jev 判的、你手工加的、Jev 不可达时默认拒的——最后一种是它可能确实需要、 你一键就能放行的域名。</p><p>删除不是放行：删掉之后，下次再有命令问到它，重新判定。</p><h2 id="最近拦截" tabindex="-1">最近拦截 <a class="header-anchor" href="#最近拦截" aria-label="Permalink to &quot;最近拦截&quot;">​</a></h2><p>最近三条被拦下的气泡，查看全部 跳到日志里筛好的 出口审查 记录。</p>',14)])])}const u=a(o,[["render",s]]);export{_ as __pageData,u as default};
